function nodesBetweenCriticalPoints(head) {
  let first = -1;
  let last = -1;
  let minDistance = Infinity;
  let prev = head;
  let node = head.next;
  let index = 1;

  while (node.next !== null) {
    const next = node.next;
    const isPeak = node.val > prev.val && node.val > next.val;
    const isValley = node.val < prev.val && node.val < next.val;
    if (isPeak || isValley) {
      if (first === -1) {
        first = index;
      } else {
        minDistance = Math.min(minDistance, index - last);
      }
      last = index;
    }
    prev = node;
    node = next;
    index++;
  }
  if (minDistance === Infinity) {
    return [-1, -1];
  }
  return [minDistance, last - first];
}

