function nodesBetweenCriticalPoints(head) {
  const values = [];
  for (let p = head; p; p = p.next) values.push(p.val);
  const critical = [];
  for (let i = 1; i + 1 < values.length; i++) {
    const a = values[i - 1], b = values[i], c = values[i + 1];
    if ((b > a && b > c) || (b < a && b < c)) critical.push(i);
  }
  if (critical.length < 2) return [-1, -1];
  let lo = Infinity, hi = -Infinity;
  for (let x = 0; x < critical.length; x++)
    for (let y = x + 1; y < critical.length; y++) {
      const d = critical[y] - critical[x];
      lo = Math.min(lo, d);
      hi = Math.max(hi, d);
    }
  return [lo, hi];
}

