function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const top = rand() < 0.7 ? int(1, 4) : 100000;
    return [Array.from({ length: int(2, 10) }, () => int(1, top))];
  }
  const n = 2000;
  const shape = int(0, 3);
  if (shape === 0) return [Array.from({ length: n }, () => int(1, 100000))];
  if (shape === 1) return [Array.from({ length: n }, () => int(1, 3))];
  if (shape === 2) {
    // Long flat or rising stretches with only a few critical points far apart.
    const list = [];
    let value = int(1, 50000);
    while (list.length < n) {
      const run = int(50, 600);
      const step = int(0, 2);
      for (let k = 0; k < run && list.length < n; k++) list.push(Math.min(100000, value + k * step));
      value = int(1, 100000);
    }
    return [list];
  }
  return [Array.from({ length: n }, (_, i) => (i % 2 === 0 ? int(1, 50000) : int(50001, 100000)))];
}
